package solucion

import "testing"

func TestSumaPares(t *testing.T) {
	casos := []struct {
		nums []int
		quiero int
	}{
		{[]int{1, 2, 3, 4}, 6},
		{nil, 0},
	}
	for _, c := range casos {
		if got := SumaPares(c.nums); got != c.quiero {
			t.Errorf("SumaPares(%v) = %d, quiero %d", c.nums, got, c.quiero)
		}
	}
}
